"use client";
import Profile from "@/app/features/user/components/Profile";
import { useUser } from "@/app/features/user/context/UserContext";
import { useProfile } from "@/app/features/user/hooks/useProfile";
import { useEffect,useRef,useState } from "react";
import styles from "./ProfilePage.module.css";

export default function ProfilePage() {
  const { user } = useUser();
  const { uploadAvatar } = useProfile();

  // State lưu URL ảnh preview tạm thời
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);

  // Ref để kết nối với thẻ input file bị ẩn
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Dọn dẹp URL Object khi component unmount để tránh rò rỉ bộ nhớ
  useEffect(() => {
    return () => {
      if (previewUrl) {
        URL.revokeObjectURL(previewUrl);
      }
    };
  }, [previewUrl]);

  // Kích hoạt input file ẩn khi bấm vào nút máy ảnh
  const handleEditClick = () => {
    fileInputRef.current?.click();
  };

  // Xử lý khi người dùng chọn file xong
  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // 1. Tạo URL tạm để hiển thị preview ngay lập tức
      const objectUrl = URL.createObjectURL(file);
      setPreviewUrl(objectUrl);

      // 2. Sử dụng hook để upload
      try {
        await uploadAvatar(file);
        // Thành công: Xóa preview khi đã có ảnh thật từ DB (hook đã gọi refreshUser)
        setPreviewUrl(null);
      } catch {
        // Thất bại: Trả lại trạng thái cũ
        setPreviewUrl(null);
      }
    }
  };

  // Logic hiển thị Avatar: Ưu tiên ảnh Preview -> Ảnh User từ DB -> Ảnh mặc định
  // Lưu ý: Sửa lại user?.avatar theo đúng key trong database của bạn nhé
  const displayAvatar =
    previewUrl || user?.avatar || "/images/Avatar/avt01.png";

  return (
    <div className={styles.pageContainer}>
      <div className={styles.heroSection}>
        <div className={styles.coverPhoto}></div>

        <div className={styles.userInfo}>
          <div className={styles.avatarWrapper}>
            <img
              src={displayAvatar}
              alt="User Avatar"
              className={styles.largeAvatar}
            />

            <input
              type="file"
              ref={fileInputRef}
              onChange={handleFileChange}
              accept="image/*"
              style={{ display: "none" }}
            />

            <button
              className={styles.editAvatarBtn}
              onClick={handleEditClick}
              title="Thay đổi ảnh đại diện"
              type="button"
            >
              {/* Icon Camera SVG */}
              <svg
                width="20"
                height="20"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"></path>
                <circle cx="12" cy="13" r="4"></circle>
              </svg>
            </button>
          </div>

          <h2 className={styles.displayName}>
            {user?.username || "Người dùng"}
          </h2>
          <span className={styles.premiumBadge}>
            <svg viewBox="0 0 576 512" height="1em">
              <path
                className={styles.logoIcon}
                d="M309 106c11.4-7 19-19.7 19-34c0-22.1-17.9-40-40-40s-40 17.9-40 40c0 14.4 7.6 27 19 34L209.7 220.6c-9.1 18.2-32.7 23.4-48.6 10.7L72 160c5-6.7 8-15 8-24c0-22.1-17.9-40-40-40S0 113.9 0 136s17.9 40 40 40c.2 0 .5 0 .7 0L86.4 427.4c5.5 30.4 32 52.6 63 52.6H426.6c30.9 0 57.4-22.1 63-52.6L535.3 176c.2 0 .5 0 .7 0c22.1 0 40-17.9 40-40s-17.9-40-40-40s-40 17.9-40 40c0 9 3 17.3 8 24l-89.1 71.3c-15.9 12.7-39.5 7.5-48.6-10.7L309 106z"
              ></path>
            </svg>
            Premium Member
          </span>
        </div>
      </div>

      <div className={styles.formContainer}>
        <Profile />
      </div>
    </div>
  );
}

"use client";
import type { SongDto } from '@/app/types/api';
import { formatDate,formatDuration } from "@/app/utils/dateHelper";
import { useEffect } from "react";
import styles from "./SongDetailModal.module.css";

interface Props {
  song: SongDto;
  onClose: () => void;
  onApprove: (id: number) => void;
  onReject: (id: number) => void;
  loading: boolean;
}

export default function SongDetailModal({
  song,
  onClose,
  onApprove,
  onReject,
  loading,
}: Props) {
  // Đóng modal khi bấm Escape
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [onClose]);

  const genres =
    song.genres?.map((g) => g.name).join(", ") || "Chưa có";
  const artists =
    song.artists?.map((a) => a.name).join(", ") || "Unknown";

  return (
    <div className={styles.overlay} onClick={onClose}>
      <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div className={styles.modalHeader}>
          <h2>Chi tiết bài hát</h2>
          <button className={styles.closeBtn} onClick={onClose}>
            ×
          </button>
        </div>

        {/* Body */}
        <div className={styles.body}>
          {/* Cover + basic info */}
          <div className={styles.topRow}>
            {song.image_url ? (
              <img
                src={song.image_url}
                alt={song.title}
                className={styles.cover}
              />
            ) : (
              <div className={styles.coverPlaceholder}>🎵</div>
            )}

            <div className={styles.basicInfo}>
              <h3 className={styles.songTitle}>{song.title}</h3>
              <p className={styles.artistName}>Nghệ sĩ: {artists}</p>
              <span className={styles.pendingBadge}>⏳ Chờ duyệt</span>
            </div>
          </div>

          {/* Meta grid */}
          <div className={styles.metaGrid}>
            <div className={styles.metaItem}>
              <div className={styles.metaLabel}>Người gửi</div>
              <div className={styles.metaValue}>
                {song.uploader?.username || "—"}
              </div>
            </div>

            <div className={styles.metaItem}>
              <div className={styles.metaLabel}>Email</div>
              <div className={styles.metaValue}>
                {song.uploader?.email || "—"}
              </div>
            </div>

            <div className={styles.metaItem}>
              <div className={styles.metaLabel}>Thể loại</div>
              <div className={styles.metaValue}>{genres}</div>
            </div>

            <div className={styles.metaItem}>
              <div className={styles.metaLabel}>Thời lượng</div>
              <div className={styles.metaValue}>
                {formatDuration(song.duration)}
              </div>
            </div>

            <div className={styles.metaItem}>
              <div className={styles.metaLabel}>Ngày gửi</div>
              <div className={styles.metaValue}>
                {formatDate(song.created_at)}
              </div>
            </div>

            <div className={styles.metaItem}>
              <div className={styles.metaLabel}>Song ID</div>
              <div className={styles.metaValue}>#{song.song_id}</div>
            </div>
          </div>

          {/* Audio player */}
          <div className={styles.audioSection}>
            <div className={styles.audioLabel}>
              🎧 Nghe thử bài hát
            </div>
            <audio
              controls
              src={song.audio_url}
              className={styles.audioPlayer}
              preload="metadata"
            >
              Trình duyệt không hỗ trợ phát nhạc.
            </audio>
          </div>
        </div>

        {/* Approve / Reject actions */}
        <div className={styles.actions}>
          <button
            className={styles.approveBtn}
            onClick={() => {
              onApprove(song.song_id);
              onClose();
            }}
            disabled={loading}
          >
            ✓ Duyệt bài hát
          </button>
          <button
            className={styles.rejectBtn}
            onClick={() => {
              onReject(song.song_id);
              onClose();
            }}
            disabled={loading}
          >
            ✕ Từ chối
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";
import Pagination from "@/app/components/ui/Pagination";
import {
approveSongApi,
fetchPendingSongs,
rejectSongApi,
} from "@/app/features/song/song.api";
import { errorMessage } from "@/app/lib/error-message";
import { useAuthState } from '@/app/lib/use-auth-state';
import styles from "@/app/styles/AdminPage/ManageSong.module.css";
import type { SongDto,SongPageDto } from '@/app/types/api';
import { formatDate,formatDuration } from "@/app/utils/dateHelper";
import { useSearchParams } from "next/navigation";
import { Suspense,useState } from "react";
import useSWR from 'swr';
import pendingStyles from "./PendingSongs.module.css";
import SongDetailModal from "./SongDetailModal";

function PendingSongsContent() {
  const searchParams = useSearchParams();
  const currentPage = Number(searchParams.get("page")) || 1;
  const auth = useAuthState('admin');
  const { data, error, isLoading, mutate } = useSWR<SongPageDto>(auth.principal ? ['pending-songs', auth.principal.userId, auth.epoch, currentPage] : null, () => fetchPendingSongs({ page: currentPage, limit: 20 }));
  const songs = data?.data ?? [], totalPages = data?.pagination.totalPages ?? 1;
  const [busy, setLoading] = useState(false);
  const loading = isLoading || busy;
  const [selectedSong, setSelectedSong] = useState<SongDto | null>(null);

  const handleApprove = async (songId: number) => {
    if (!confirm("Bạn có chắc muốn duyệt bài hát này?")) return;
    try {
      setLoading(true);
      await approveSongApi(songId);
      await mutate();
      if (selectedSong?.song_id === songId) setSelectedSong(null);
    } catch (error: unknown) {
      alert(errorMessage(error, "Duyệt thất bại"));
    } finally {
      setLoading(false);
    }
  };

  const handleReject = async (songId: number) => {
    if (!confirm("Bạn có chắc muốn từ chối bài hát này?")) return;
    try {
      setLoading(true);
      await rejectSongApi(songId);
      await mutate();
      if (selectedSong?.song_id === songId) setSelectedSong(null);
    } catch (error: unknown) {
      alert(errorMessage(error, "Từ chối thất bại"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.container}>
      <h2 className={styles.header}>Duyệt bài hát</h2>
      {error && <div role="alert">Không tải được danh sách.<button onClick={() => void mutate()}>Thử lại</button></div>}

      {songs.length === 0 && !loading ? (
        <div className={pendingStyles.emptyState}>
          <span className={pendingStyles.emptyIcon}>✅</span>
          <h3>Không có bài hát nào đang chờ duyệt</h3>
          <p>Tất cả bài hát đã được xử lý.</p>
        </div>
      ) : (
        <table className={styles.songTable}>
          <colgroup>
            <col style={{ width: "20%" }} />
            <col style={{ width: "12%" }} />
            <col style={{ width: "12%" }} />
            <col style={{ width: "14%" }} />
            <col style={{ width: "14%" }} />
            <col style={{ width: "8%" }} />
            <col style={{ width: "20%" }} />
          </colgroup>
          <thead>
            <tr>
              <th>Tên bài hát</th>
              <th>Nghệ sĩ</th>
              <th>Người gửi</th>
              <th>Thể loại</th>
              <th>Ngày gửi</th>
              <th>Thời lượng</th>
              <th>Hành động</th>
            </tr>
          </thead>

          <tbody>
            {songs.map((song) => (
              <tr key={song.song_id}>
                <td>
                  <div className={pendingStyles.songTitle}>
                    {song.image_url && (
                      <img
                        src={song.image_url}
                        alt=""
                        className={pendingStyles.songThumb}
                      />
                    )}
                    <span>{song.title}</span>
                  </div>
                </td>
                <td>
                  {song.artists?.map((a) => a.name).join(", ") ||
                    "Unknown"}
                </td>
                <td>
                  <span className={pendingStyles.uploaderName}>
                    {song.uploader?.username || "—"}
                  </span>
                </td>
                <td>{song.genres?.map((g) => g.name).join(", ") || "—"}</td>
                <td>{formatDate(song.created_at)}</td>
                <td>{formatDuration(song.duration)}</td>
                <td>
                  <div className={pendingStyles.actionGroup}>
                    <button
                      className={pendingStyles.viewBtn}
                      onClick={() => setSelectedSong(song)}
                    >
                      👁 Xem
                    </button>
                    <button
                      className={pendingStyles.approveBtn}
                      onClick={() => handleApprove(song.song_id)}
                      disabled={loading}
                    >
                      ✓ Duyệt
                    </button>
                    <button
                      className={pendingStyles.rejectBtn}
                      onClick={() => handleReject(song.song_id)}
                      disabled={loading}
                    >
                      ✕ Từ chối
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <Pagination currentPage={currentPage} totalPages={totalPages} />

      {selectedSong && (
        <SongDetailModal
          song={selectedSong}
          onClose={() => setSelectedSong(null)}
          onApprove={handleApprove}
          onReject={handleReject}
          loading={loading}
        />
      )}
    </div>
  );
}

export default function PendingSongsPage() {
  return (
    <Suspense fallback={<div>Loading...</div>}>
      <PendingSongsContent />
    </Suspense>
  );
}

"use client";
interface PlaylistCoverProps {
  images: string[];
  size?: number | string;
}

export default function PlaylistCover({
  images,
  size = 180,
}: PlaylistCoverProps) {
  const covers = images.slice(0, 4);

  if (covers.length === 0) {
    return (
      <img
        src="/images/default-song.jpg"
        alt="Default Playlist Cover"
        style={{
          width: size,
          height: size,
          objectFit: "cover",
        }}
      />
    );
  }

  if (covers.length === 1) {
    return (
      <img
        src={covers[0]}
        alt="Playlist cover"
        style={{
          width: size,
          height: size,
          objectFit: "cover",
        }}
      />
    );
  }

  if (covers.length === 2) {
    return (
      <div
        style={{
          width: size,
          height: size,
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          overflow: "hidden",
        }}
      >
        <img src={covers[0]} alt="Cover 1" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        <img src={covers[1]} alt="Cover 2" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
      </div>
    );
  }

  if (covers.length === 3) {
    return (
      <div
        style={{
          width: size,
          height: size,
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gridTemplateRows: "1fr 1fr",
          overflow: "hidden",
        }}
      >
        <img src={covers[0]} alt="Cover 1" style={{ width: "100%", height: "100%", objectFit: "cover", gridRow: "1 / span 2" }} />
        <img src={covers[1]} alt="Cover 2" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        <img src={covers[2]} alt="Cover 3" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
      </div>
    );
  }

  // 4 or more covers
  return (
    <div
      style={{
        width: size,
        height: size,
        display: "grid",
        gridTemplateColumns: "1fr 1fr",
        gridTemplateRows: "1fr 1fr",
        overflow: "hidden",
      }}
    >
      {covers.map((img, index) => (
        <img
          key={index}
          src={img}
          alt={`Cover ${index + 1}`}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
          }}
        />
      ))}
    </div>
  );
}

"use client";
import Link from "next/link";
import { useCallback,useEffect,useRef,useState } from "react";
import { FaPause,FaPlay } from "react-icons/fa";

import { usePlayer } from "@/app/features/player/context/PlayerContext";
import { fetchDailySongs } from "@/app/features/song/song.api";
import type { Track } from "@/app/types/music";

const TrackSection = () => {
  const [tracks, setTracks] = useState<Track[]>([]);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const { setPlaylist, isPlaying, togglePlay, currentTrack } = usePlayer();
  const [hasMore, setHasMore] = useState(true);

  const flightRef = useRef<AbortController | null>(null);
  const generationRef = useRef(0);
  const pageRef = useRef(1);
  const moreRef = useRef(true);
  const failedRef = useRef(false);
  const tracksRef = useRef<Track[]>([]);
  const [error, setError] = useState<string | null>(null);
  const loadSongs = useCallback(async (retry = false) => {
    if (flightRef.current || !moreRef.current || (failedRef.current && !retry)) return;
    const controller = new AbortController(), generation = generationRef.current, requested = pageRef.current;
    flightRef.current = controller; failedRef.current = false; setLoading(true); setError(null);
    try {
      const res = await fetchDailySongs(20, requested, AbortSignal.any([controller.signal, AbortSignal.timeout(10000)]));
      if (generation !== generationRef.current) return;
      if (res.page !== requested) throw new Error('Invalid catalog cursor');
      const merged = Array.from(new Map([...tracksRef.current, ...res.songs].map((song) => [song.trackId, song])).values());
      moreRef.current = res.songs.length > 0 && merged.length > tracksRef.current.length && merged.length < res.total;
      tracksRef.current = merged; pageRef.current = requested + 1;
      setTracks(merged); setPage(pageRef.current); setHasMore(moreRef.current);
    } catch {
      if (generation !== generationRef.current) return;
      failedRef.current = true; setError('Không tải được danh sách bài hát. Vui lòng thử lại.');
    } finally {
      if (flightRef.current === controller) { flightRef.current = null; setLoading(false); }
    }
  }, []);
  useEffect(() => {
    const generation = ++generationRef.current;
    let active = true;
    queueMicrotask(() => { if (active) void loadSongs(); });
    return () => { active = false; generationRef.current = generation + 1; flightRef.current?.abort(); flightRef.current = null; };
  }, [loadSongs]);
  if (!tracks.length && error) return <div role="alert">{error}<button onClick={() => void loadSongs(true)}>Thử tải danh sách</button></div>;
  if (!tracks.length && loading) return <div>Đang tải bài hát…</div>;
  if (!tracks.length) return <div>Chưa có bài hát</div>;

  return (
    <div
      className="list-container"
      onScroll={(e) => {
        const target = e.currentTarget;

        if (
          target.scrollTop + target.clientHeight >=
          target.scrollHeight - 100
        ) {
          loadSongs();
        }
      }}
    >
      {tracks.map((song: Track, index) => (
        <div
          key={song.trackId}
          className={`list-item ${currentTrack?.trackId === song.trackId ? "playing" : ""}`}
          onClick={() => {
            if (currentTrack?.trackId === song.trackId) {
              // Nếu đang là bài hiện tại → toggle play/pause
              togglePlay();
            } else {
              // Nếu là bài khác → play bài mới
              setPlaylist(tracks, index, "radio", { nextPage: page, hasMore, pageSize: 20 });
            }
          }}
        >
          <p>{index + 1}</p>
          <img src={song.imageUrl} alt={song.title} />

          <div className="track-info">
            <h3><Link href={`/songs/${song.trackId}`} onClick={(event) => event.stopPropagation()}>{song.title}</Link></h3>
            <p>{song.artistName}</p>
          </div>

          <div
            className="play-icon"
            onClick={(e) => {
              e.stopPropagation();

              if (currentTrack?.trackId === song.trackId) {
                togglePlay();
              } else {
                setPlaylist(tracks, index, "radio", { nextPage: page, hasMore, pageSize: 20 });
              }
            }}
          >
            {currentTrack?.trackId === song.trackId && isPlaying ? (
              <FaPause />
            ) : (
              <FaPlay />
            )}
          </div>
        </div>
      ))}
      {error && <div role="alert">{error}<button onClick={() => void loadSongs(true)}>Thử tải danh sách</button></div>}
      {loading && <div role="status">Đang tải bài hát…</div>}
    </div>
  );
};

export default TrackSection;

"use client";
import "@/app/components/layout/Header/AdminPage/Header.css";
import { useAdminUser } from "@/app/features/admin/context/AdminUserContext";
import { useRouter } from "next/navigation";
// import { logoutAdmin } from "@/app/utils/authApi";
import { logoutAdminService } from "@/app/features/admin/service";

export default function Header() {
  const { admin, setAdmin, loading } = useAdminUser();
  const router = useRouter();

  if (loading) return null;

  const handleLogout = async () => {
    try {
      await logoutAdminService();
      setAdmin(null);
      router.replace("/administrator/login");
    } catch (error) {
      console.error("Lỗi khi đăng xuất:", error);
      alert("Đăng xuất thất bại!");
    }
  };

  return (
    <div className="header">
      <div
        className="header-left"
        onClick={() => {
          router.push("/administrator");
        }}
      >
        <img src="../images/Logo/admin-logo.png" alt="logo web page" />
        <h2 id="page-title">Dashboard</h2>
      </div>

      <div className="header-center">
        {/* Sidebar moved to layout */}
      </div>

      <div className="header-right">
        {admin ? (
          <>
            <span>Hi, {admin.username}</span>
            <i className="fa-solid fa-user"></i>
            <button onClick={handleLogout} className="logout-from-dashboard">
              <i className="fa-solid fa-power-off"></i> log out
            </button>
          </>
        ) : (
          <>
            <i className="fa-solid fa-user"></i>
            <button
              className="logout-from-dashboard"
              onClick={() => {
                router.push("/administrator/login");
              }}
            >
              Sign in
            </button>
          </>
        )}
      </div>
    </div>
  );
}

"use client";
import styles from "@/app/components/layout/Header/UserPage/Header.module.css";
import { useModal } from "@/app/context/ModalContext";
import { useUser } from "@/app/features/user/context/UserContext";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { useLogout } from "../../../../features/auth/useLogout";
import PopUp from "../../../ui/PopUp";
import SearchBarComponent from "../../../ui/SearchBar/SearchBarComponent";

export default function Header() {
  const [showUserMenu, setShowUserMenu] = useState(false);
  const { openModal } = useModal();
