/*  RecommendSongCard — Card component chung                           */
/* ------------------------------------------------------------------ */
interface CardProps {
  song: RecommendationSong;
  isActive: boolean;
  isPlaying: boolean;
  isDevMode: boolean;
  variant?: "grid" | "list"; // grid = dạng dọc (RecommendationSection), list = dạng ngang (SimilarSongsSection)
  onClick: () => void;
}

const RecommendSongCard: React.FC<CardProps> = ({
  song,
  isActive,
  isPlaying,
  isDevMode,
  variant = "grid",
  onClick,
}) => {
  const [hovered, setHovered] = useState(false);
  const tags = extractTags(song.reason);
  const scoreBars = extractScoreBars(song);

  const showPopover = isDevMode && hovered;

  if (variant === "list") {
    /* ---- LIST variant (SimilarSongsSection) ---- */
    return (
      <div
        className={`similar-item${isActive ? " similar-item--active" : ""}`}
        onClick={onClick}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        title={song.title}
        style={{ position: "relative" }}
      >
        {/* Thumbnail */}
        <div className="similar-img-wrap">
          {song.imageUrl ? (
            <img src={song.imageUrl} alt={song.title} className="similar-img" />
          ) : (
            <div className="similar-img-placeholder">🎵</div>
          )}
          <div className="similar-play-overlay">
            {isActive && isPlaying ? <FaPause /> : <FaPlay />}
          </div>

          {/* Visual tags trên ảnh (user mode) */}
          {!isDevMode && tags.length > 0 && (
            <div className="rec-tags-on-img">
              {tags.map((t) => (
                <span key={t.label} className="rec-tag rec-tag--img">
                  {t.emoji}
                </span>
              ))}
            </div>
          )}
        </div>

        {/* Info */}
        <div className="similar-info">
          <span className="similar-title">{song.title}</span>
          <span className="similar-artist">{song.artistName}</span>

          {/* Visual tags dưới artist (user mode) */}
          {!isDevMode && tags.length > 0 && (
            <div className="rec-tags-row">
              {tags.map((t) => (
                <span key={t.label} className="rec-tag">
                  {t.emoji} {t.label}
                </span>
              ))}
            </div>
          )}

          {/* Dev mode: icon indicator */}
          {isDevMode && (
            <span className="rec-dev-icon" title="Xem thông số AI">🤖</span>
          )}
        </div>

        {/* Dev mode Popover */}
        {showPopover && (
          <AiPopover song={song} scoreBars={scoreBars} />
        )}
      </div>
    );
  }

  /* ---- GRID variant (RecommendationSection) ---- */
  return (
    <div
      className={`rec-card${isActive ? " rec-card--active" : ""}`}
      onClick={onClick}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      title={song.title}
      style={{ position: "relative" }}
    >
      {/* Cover art */}
      <div className="rec-card-img-wrap">
        {song.imageUrl ? (
          <img src={song.imageUrl} alt={song.title} className="rec-card-img" />
        ) : (
          <div className="rec-card-img-placeholder">🎵</div>
        )}
        <div className="rec-card-overlay">
          {isActive && isPlaying ? <FaPause /> : <FaPlay />}
        </div>

        {/* Visual tags trên góc ảnh */}
        {!isDevMode && tags.length > 0 && (
          <div className="rec-tags-on-img">
            {tags.map((t) => (
              <span key={t.label} className="rec-tag rec-tag--img">
                {t.emoji}
              </span>
            ))}
          </div>
        )}

        {/* Dev mode badge */}
        {isDevMode && (
          <div className="rec-dev-badge">🤖</div>
        )}
      </div>

      {/* Info */}
      <div className="rec-card-body">
        <h3 className="rec-card-title">{song.title}</h3>
        <p className="rec-card-artist">{song.artistName}</p>

        {/* Visual tags dưới artist (user mode) */}
        {!isDevMode && tags.length > 0 && (
          <div className="rec-tags-row">
            {tags.map((t) => (
              <span key={t.label} className="rec-tag">
                {t.emoji} {t.label}
              </span>
            ))}
          </div>
        )}
      </div>

      {/* Dev mode Popover */}
      {showPopover && (
        <AiPopover song={song} scoreBars={scoreBars} />
      )}
    </div>
  );
};

/* ------------------------------------------------------------------ */
/* AiPopover — Hover overlay trong Dev Mode                            */
/* ------------------------------------------------------------------ */
interface PopoverProps {
  song: RecommendationSong;
  scoreBars: ScoreBar[];
}

const AiPopover: React.FC<PopoverProps> = ({ song, scoreBars }) => {
  // Bao quát cả 2 API (Similar dùng finalScore, User Rec dùng accumulatedScore)
  const mainScore = song.finalScore;

  return (
    // Xóa onClick={(e) => e.stopPropagation()} để khi click vào Popover vẫn phát nhạc được
    <div className="ai-popover">
      <div className="ai-popover-header">
        <span>🤖 Explainable AI</span>
      </div>

      {/* Điểm tổng hợp */}
      {mainScore !== undefined && (
        <div className="ai-popover-row">
          <span className="ai-popover-label">Điểm tổng hợp</span>
          <span className="ai-popover-value ai-popover-value--highlight">
            {Number(mainScore).toFixed(4)}
          </span>
        </div>
      )}

      {/* Progress bars */}
      {scoreBars.length > 0 && (
        <div className="ai-popover-bars">
          {scoreBars.map((bar) => (
            <div key={bar.label} className="ai-bar-row">
              <span className="ai-bar-label">{bar.label}</span>
              <div className="ai-bar-track">
                <div
                  className="ai-bar-fill"
                  style={{
                    width: `${Math.min(bar.value * 100, 100).toFixed(1)}%`,
                    background: bar.color,
                  }}
                />
              </div>
              <span className="ai-bar-num">{bar.value.toFixed(2)}</span>
            </div>
          ))}
        </div>
      )}

      {/* Lý do nguyên văn */}
      {song.reason && (
        <div className="ai-popover-reason">
          <span className="ai-popover-label">Lý do đề xuất:</span>
          <p className="ai-popover-reason-text">{song.reason}</p>
        </div>
      )}
    </div>
  );
};

export default RecommendSongCard;

"use client";
import { usePlayer } from '@/app/features/player/context/PlayerContext';
import { formError } from '@/app/lib/form-error';
import { useLikeContext } from "@/app/features/like/context/LikeContext";
import type { Track } from "@/app/types/music";
import { useRating } from "@/app/features/rating/useRating";
import "@/app/features/song/components/DetailSong/DetailSong.css";
import { useRouter } from "next/navigation";
import { useEffect,useState } from "react";
import { IoIosArrowBack } from "react-icons/io";

const DetailSong = ({ track: currentTrack }: { track: Track }) => {
  const router = useRouter();
  const { setPlaylist } = usePlayer();
  const [actionError, setActionError] = useState("");




  const [hoverRating, setHoverRating] = useState(0);
  const { submitRating, fetchRatingData, userRating, summary, loading } = useRating();

  const { likedMap, toggleLike, fetchLikeStatus } = useLikeContext();

  // THÊM STATE KHÓA NÚT LIKE
  const [isLiking, setIsLiking] = useState(false);

  // HÀM XỬ LÝ TRÁNH SPAM CLICK
  const handleLikeClick = async () => {
    if (!currentTrack || isLiking) return;

    setIsLiking(true);
    try {
      await toggleLike(currentTrack.trackId);
    } catch (error) {
      setActionError(formError(error));
    } finally {
      setTimeout(() => {
        setIsLiking(false);
      }, 500);
    }
  };

  // Lấy trạng thái like của bài hát hiện tại
  const liked = currentTrack ? likedMap[currentTrack.trackId] || false : false;

  useEffect(() => {
    if (currentTrack?.trackId) {
      fetchRatingData(currentTrack.trackId);
      fetchLikeStatus(currentTrack.trackId);
    }
  }, [currentTrack?.trackId, fetchRatingData, fetchLikeStatus]);

  if (!currentTrack) {
    return (
      <div className="detail-container">
        <div className="content-wrapper">
          <h2 style={{ textAlign: "center", width: "100%" }}>
            Chưa có bài hát nào đang phát...
          </h2>
        </div>
      </div>
    );
  }

  return (
    <div className="detail-container">
      <button className="back-btn-detail" onClick={() => router.back()}>
        <IoIosArrowBack />
      </button>

      <div
        className="background-blur"
        style={{ backgroundImage: `url(${currentTrack.imageUrl})` }}
      ></div>

      <div className="content-wrapper">
        <div className="left-section">
          <div className="image-card">
            <img src={currentTrack.imageUrl} alt={currentTrack.title} />

          </div>

          {actionError && <p role="alert">{actionError}</p>}
          <button onClick={() => setPlaylist([currentTrack], 0)}>Phát bài hát</button>
          <div className="song-actions-detail">
            <button
              className={`icon-btn like-icon ${liked ? "liked" : ""}`}
              onClick={handleLikeClick}
              disabled={isLiking}
              style={{ opacity: isLiking ? 0.6 : 1 }}
            >
              <i
                className={liked ? "fa-solid fa-heart" : "fa-regular fa-heart"}
              />{" "}
              <p>Like</p>
            </button>


          </div>

          <div className="rating-section-inline">
            <h2 className="rating-title">Đánh giá bài hát</h2>

            <div className="stars">
              {[1, 2, 3, 4, 5].map((star) => (
                <button disabled={loading}
                  aria-label={`Đánh giá ${star} sao`}
                  key={star}
                  className={`fa-star ${
                    (hoverRating || userRating || 0) >= star
                      ? "fa-solid filled"
                      : "fa-regular"
                  }`}
                  onMouseEnter={() => setHoverRating(star)}
                  onMouseLeave={() => setHoverRating(0)}
                  onClick={() => { void submitRating(currentTrack.trackId, star).catch((error) => setActionError(formError(error))); }}
                />
              ))}

            </div>

            <p className="rating-text">
              {userRating
                ? `Bạn đã đánh giá ${userRating} / 5`
                : "Chưa đánh giá"} ({summary.totalRatings})
            </p>



          </div>


        </div>
        <div className="right-section">
          <div className="song-info">
            <h1>{currentTrack.title}</h1>
            <p>{currentTrack.artistName}</p>
          </div>

        </div>
      </div>




    </div>
  );
};

export default DetailSong;

"use client";
import Link from "next/link";
import { useLikeContext } from "@/app/features/like/context/LikeContext";
import { usePlayer } from "@/app/features/player/context/PlayerContext";
import "@/app/features/song/components/LibraryTable/LibraryTable.css";
import type { Track } from "@/app/types/music";
import { formatDuration } from "@/app/utils/dateHelper";
import React from "react";

const LibraryTable: React.FC = () => {
  const { setPlaylist, currentTrack } = usePlayer();
  const { likedSongsList, likedMap, toggleLike, loading, loadingMore, hasMore, listError, loadMore, fetchLikedSongsList } = useLikeContext();

  const handlePlay = (index: number) => {
    setPlaylist(likedSongsList, index);
  };

  if (loading) return <div role="status">Đang tải thư viện…</div>;
  if (!likedSongsList.length && !listError) {
    return <div className="empty">Bạn chưa thích bài hát nào</div>;
  }

  return (
    <div id="table_row">
      {likedSongsList.map((song: Track, index: number) => {
        const isActive = currentTrack?.trackId === song.trackId;

        return (
          <div
            className={`row ${isActive ? "active" : ""}`}
            key={song.trackId}
            onClick={() => handlePlay(index)}
          >
            <div className="col_index">{index + 1}</div>

            <div className="col_title">
              <img src={song.imageUrl} alt="" />
              <Link href={`/songs/${song.trackId}`} onClick={(event) => event.stopPropagation()}>{song.title}</Link>
            </div>

            <div className="col_artist">{song.artistName}</div>

            <div className="col_duration library-actions">{formatDuration(song.duration)}
            <button aria-label={`Bỏ yêu thích ${song.title}`} aria-pressed={likedMap[song.trackId] ?? true} onClick={(event) => { event.stopPropagation(); void toggleLike(song.trackId).catch(() => {}); }}>♥</button></div>
          </div>
        );
      })}
      {listError && <div role="alert">{listError}<button onClick={() => void fetchLikedSongsList().catch(() => {})}>Thử tải lại thư viện</button></div>}
      {hasMore && <button disabled={loadingMore || Boolean(listError)} onClick={() => void loadMore().catch(() => {})}>{loadingMore ? 'Đang tải…' : 'Tải thêm bài hát'}</button>}
    </div>
  );
};

export default LibraryTable;
